import {evaluate} from './engine.js';
const stages=['preflop','flop','turn','river'],counts={preflop:0,flop:3,turn:4,river:5};
const focus={preflop:'Choose a starting range for your position and the price. Strong hands usually want value; marginal hands need a reason to enter.',flop:'Compare your made hand and draws with the board. Decide whether a bet gets called by worse hands or makes better hands fold.',turn:'Reassess the new card and the larger pot. Only one card remains: a draw needs a suitable price, and a big pot needs a clear plan.',river:'No more cards are coming. Value bet when worse hands can call; bluff only when better hands can fold; call based on plausible value hands and bluffs.'};
function boardNote(board){if(!board.length)return 'No shared cards yet.';const suits=board.map(c=>c[1]),ranks=board.map(c=>c[0]),flush=Math.max(...suits.map(s=>suits.filter(t=>t===s).length));return [...new Set(ranks)].length<ranks.length?'Paired board: full houses and trips can change relative strength.':flush>=3?'Three or more cards share a suit: account for possible flushes.':'Check which straights, pairs and draws this board supports.';}
function advice(hole,d,board){const hand=board.length>=3?evaluate([...hole,...board]):null,ranks=hole.map(c=>'23456789TJQKA'.indexOf(c[0])+2),premium=(ranks[0]===ranks[1]&&ranks[0]>=10)||(ranks.includes(14)&&Math.min(...ranks)>=12);
 if(d.type==='fold'&&d.owed===0)return 'Check for free instead of folding. Keep the option to win without committing another chip.';
 if(d.street==='preflop'){
  if(premium)return d.currentBet<=20?'A strong starting hand generally supports a value raise. Choose a size with position, limpers and effective stacks in mind.':'Against a raise, compare value re-raising with calling. Stack depth and how tight the raiser is matter; a strong starting hand is not automatic permission to stack off.';
  if(d.owed===0)return 'Use the free check with hands that do not benefit from a raise. Raise only with a value or bluff plan, rather than paying just to see what happens.';
  return 'With a non-premium hand, be selective—especially in early position or facing a raise. Suitedness, connectedness and acting later can support a call; a weak, disconnected hand often belongs in the fold group.';
 }
 if(d.street==='river'){
  if(d.type==='raise')return 'Before betting or raising, name weaker hands that would call. If there are few, consider checking; a bluff needs a believable target that can fold.';
  if(d.owed>0)return hand.category<=1?'With at most one pair, treat a large river bet cautiously. Call only if enough plausible bluffs or worse hands justify the price; otherwise consider folding.':'Compare your strong made hand with the value hands the board allows. Consider calling versus raising based on which worse hands continue; strength alone does not make a raise mandatory.';
  return 'Consider a value bet if weaker hands can call; otherwise a check can take your showdown value. There is no future card to improve a missed draw.';
 }
 if(hand.category>=2)return 'Look for value from weaker hands and draws, but compare your hand with the board’s strongest possibilities. Against heavy pressure, reassess rather than automatically building a large pot.';
 if(hand.category===1)return 'With one pair, consider keeping the pot manageable. A small value bet can work against weaker callers; strong raises or a dangerous new card are reasons to reassess.';
 return d.owed>0?'Without a made pair, separate a useful draw from weak high cards. Compare the call price with clean improving cards; if the draw or price is poor, folding is a reasonable baseline.':'A free check is a reasonable baseline with weak high cards. A semi-bluff needs improving cards and opponents who can fold; do not bet without a purpose.';
}
export function buildStreetReview(g){const choices=g.decisions??[],hole=g.players[0].hole,fold=choices.find(d=>d.type==='fold');return stages.map(street=>{
 const decisions=choices.filter(d=>d.street===street).map(d=>{const board=d.board??g.board.slice(0,counts[street]),rank=board.length>=3?evaluate([...hole,...board]).name:'Starting hand';const price=d.owed>0&&d.callPot>0?Math.round(100*d.owed/d.callPot):null;return {action:`${d.type}${d.amount?' '+d.amount:''}`,position:d.position||'Position not saved',rank,context:`${rank}. Pot ${d.pot}; ${d.owed?`${d.owed} to call`:'check available'}.${price!==null?` Call price: ${price}% of the contestable pot after calling; this is not your win probability.`:''}`,guidance:advice(hole,d,board),board};});
 const dealt=g.board.length>=counts[street],alreadyFolded=fold&&stages.indexOf(fold.street)<stages.indexOf(street);return {street,board:dealt?g.board.slice(0,counts[street]):[],focus:focus[street],texture:dealt?boardNote(g.board.slice(0,counts[street])):'',status:!dealt?'Not dealt — the hand ended earlier.':decisions.length?'Your decisions':alreadyFolded?'No decision — you had already folded.':'No voluntary decision recorded; the hand may have run out while you were all-in.',decisions};
});}
